package com.jobradar.taxonomy.role;
import java.util.Set;import com.jobradar.common.api.PaginatedResponse;import com.jobradar.common.exception.*;import com.jobradar.common.pagination.PaginationParameters;import com.jobradar.taxonomy.category.*;import com.jobradar.taxonomy.common.TaxonomySupport;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class RoleService {private static final Set<String>SORTS=Set.of("roleName","slug","opportunityCount","createdAt");private final RoleRepository repo;private final CategoryRepository categories;public RoleService(RoleRepository r,CategoryRepository c){repo=r;categories=c;}public PaginatedResponse<RoleDto> browse(String q,Integer cat,PaginationParameters p){return PaginatedResponse.from(repo.browse(blank(q),cat,TaxonomySupport.pageable(p,SORTS,"roleName")).map(RoleDto::from));}private String blank(String q){return q==null||q.isBlank()?null:q.trim();}public RoleDto bySlug(String slug){return repo.findBySlugIgnoreCaseAndActiveTrue(slug).map(RoleDto::from).orElseThrow(()->new ResourceNotFoundException("Job role not found"));}private CategoryEntity category(Integer id){CategoryEntity c=categories.findById(id).orElseThrow(()->new ResourceNotFoundException("Category not found"));if(!c.isActive())throw new BadRequestException("Category must be active");return c;}@Transactional public RoleDto create(RoleRequest r){String n=r.roleName().trim(),s=r.slug()==null||r.slug().isBlank()?TaxonomySupport.slug(n):TaxonomySupport.slug(r.slug());TaxonomySupport.duplicate(repo.existsByRoleNameIgnoreCase(n)||repo.existsBySlugIgnoreCase(s),"Job role");return RoleDto.from(repo.save(new RoleEntity(n,s,category(r.categoryId()))));}@Transactional public RoleDto update(Integer id,RoleRequest r){RoleEntity e=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Job role not found"));String n=r.roleName().trim(),s=r.slug()==null||r.slug().isBlank()?TaxonomySupport.slug(n):TaxonomySupport.slug(r.slug());TaxonomySupport.duplicate(repo.existsByRoleNameIgnoreCaseAndIdNot(n,id)||repo.existsBySlugIgnoreCaseAndIdNot(s,id),"Job role");e.update(n,s,category(r.categoryId()));return RoleDto.from(e);}@Transactional public void active(Integer id,boolean a){RoleEntity e=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Job role not found"));if(a)category(e.getCategory().getId());e.setActive(a);}}
